<?php
$title='Automations';$subtitle='Follow up automatically – WhatsApp, email, AI calls, bookings and status updates';
if(is_post()){
  $a=$_POST['a']??'';$id=(int)($_POST['id']??0);
  if($a==='delete'){DB::q("UPDATE jobs SET status='cancelled' WHERE type='auto' AND status='pending' AND ref_id IN (SELECT id FROM automation_runs WHERE automation_id=?)",[$id]);DB::q('DELETE FROM automation_runs WHERE automation_id=?',[$id]);DB::q('DELETE FROM automations WHERE id=?',[$id]);flash('Automation deleted.');}
  if($a==='template'){$t=Automation::templates()[$_POST['t']]??null;if($t){$nid=DB::insert('automations',['name'=>$t['name'],'trig'=>$t['trig'],'trig_value'=>$t['tv']??'','conditions'=>je($t['cond']??[]),'steps'=>je($t['steps']),'stop_on_reply'=>1,'active'=>0]);flash('Template added – review it and switch it on.');redirect(url('automation',['id'=>$nid]));}}
  redirect(url('automations'));}
$rows=DB::all("SELECT a.*,(SELECT COUNT(*) FROM automation_runs r WHERE r.automation_id=a.id AND r.status IN ('running','waiting')) act,(SELECT COUNT(*) FROM automation_runs r WHERE r.automation_id=a.id AND r.status='done') dn FROM automations a ORDER BY a.active DESC,a.id DESC");
$T=Automation::triggers();$AC=Automation::actions();
?>
<?php $on=count(array_filter($rows,fn($r)=>$r['active']));$run=array_sum(array_column($rows,'act'));$done=array_sum(array_column($rows,'dn'));$wk=(int)DB::val("SELECT COUNT(*) FROM automation_runs WHERE created_at>=NOW()-INTERVAL 7 DAY");$unit=fn($s)=>(int)($s['n']??1).' '.((int)($s['n']??1)===1?rtrim($s['u']??'h','s'):($s['u']??'h'));?>
<div class="stats"><?=kpi('Automations on',$on,'bot','violet',count($rows).' in total')?><?=kpi('Running now',$run,'activity','blue','leads inside a flow')?><?=kpi('Completed',$done,'check','green','finished runs')?><?=kpi('Started this week',$wk,'zap','orange','new runs in 7 days')?></div>
<?php if(!Voice::ready()||WhatsApp::provider()==='manual'||!Mailer::ready()):?><div class="al al-info"><?=icon('alert')?><span>For fully automatic follow-ups connect <?=implode(' · ',array_filter([!Mailer::ready()?'<a href="'.url('settings',['tab'=>'email']).'">Email</a>':'',WhatsApp::provider()==='manual'?'<a href="'.url('settings',['tab'=>'whatsapp']).'">WhatsApp API</a> (manual mode only prepares messages)':'',!Voice::ready()?'<a href="'.url('settings',['tab'=>'voice']).'">AI voice calls</a>':'']))?>.</span></div><?php endif?>
<div class="ph"><div><b style="font-size:15px;color:var(--ink)">Your automations</b> <span class="muted sm">· switch on, edit or remove</span></div><div class="pha"><a class="btn" href="<?=url('recipes')?>"><?=icon('spark')?>Browse ready-made recipes</a><a class="btn btn-p" href="<?=url('automation',['id'=>'new'])?>"><?=icon('plus')?>New automation</a></div></div>
<?php if(!$rows):?><div class="card"><div class="empty"><?=icon('bot','eic')?><h4>No automations yet</h4><p>Start from a ready-made recipe (welcome message, follow-up sequence, AI call…) or build your own flow.</p><div class="row" style="justify-content:center"><a class="btn btn-p" href="<?=url('recipes')?>"><?=icon('spark')?>Browse recipes</a><a class="btn" href="<?=url('automation',['id'=>'new'])?>"><?=icon('plus')?>Build from scratch</a></div></div></div><?php else:?>
<div class="aul"><?php foreach($rows as $r):$st=jd($r['steps']);?><div class="card au-row <?=$r['active']?'':'off'?>"><label class="sw" title="On / off"><input type="checkbox" <?=$r['active']?'checked':''?> onchange="A.post('index.php?r=api&do=toggle_auto',{id:<?=$r['id']?>,on:this.checked?1:''}).then(function(){A.toast('Saved')});this.closest('.au-row').classList.toggle('off',!this.checked)"><i></i></label><div class="grow"><a href="<?=url('automation',['id'=>$r['id']])?>"><b><?=e($r['name'])?></b></a><div class="au-when"><?=icon('zap')?>When <?=e(mb_strtolower($T[$r['trig']][0]??$r['trig']))?><?=$r['trig_value']!==''?' · <b>'.e($r['trig_value']).'</b>':''?></div><div class="au-flow mt"><?php foreach(array_slice($st,0,7) as $i=>$x):$a=$AC[$x['t']]??['?','zap','gray'];?><?=$i?'<em class="arr">→</em>':''?><span><?=icon($a[1])?><?=e($x['t']==='wait'?'Wait '.$unit($x):$a[0])?></span><?php endforeach?><?=count($st)>7?'<span>+'.(count($st)-7).' more</span>':''?></div></div><div class="au-n"><b><?=(int)$r['act']?></b><span>running</span></div><div class="au-n"><b><?=(int)$r['dn']?></b><span>completed</span></div><div class="row nw"><a class="btn btn-sm" href="<?=url('automation',['id'=>$r['id']])?>"><?=icon('edit')?>Edit</a><form method="post" onsubmit="return confirm('Delete this automation?')"><?=csrf_field()?><input type="hidden" name="a" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ib red" title="Delete"><?=icon('trash')?></button></form></div></div><?php endforeach?></div><?php endif?>
